mapper.sql:
SELECT ROW_NUMBER() OVER (ORDER BY apr16_appl_date DESC, apr16_appr_id DESC) AS apr16_stamp_doc_id , t.* , emp01_kor_nm AS apr16_appl_emp_nm , apr10_stamp_nm AS apr16_stamp_nm , CASE WHEN COALESCE(status_cd,'') = '' THEN null ELSE status_cd END AS apr16_appr_status_nm FROM ( SELECT apr16_appl_date , apr16_appl_emp_id , apr16_note , apr16_stamp_id , apr16_stamp_qty , apr16_stamp_out_yn , apr16_provide_co , apr16_purpose , apr01_stamp_seq AS apr16_stamp_seq , apr16_stamp_doc_id AS apr16_real_stamp_doc_id , apr16_stamp_date , apr16_appr_id , apr01_status_cd AS status_cd FROM apr16_stamp_doc LEFT JOIN apr01_appr ON apr01_appr_id = apr16_appr_id WHERE apr16_company_id = #{companyId} AND apr16_appl_date BETWEEN #{startDate} AND #{closeDate} AND apr16_appl_type = '3' AND ( ( apr16_appr_id IS NOT NULL AND COALESCE(apr01_status_cd,'99') NOT IN ('99','40') ) OR ( apr16_stamp_date IS NOT NULL ) OR ( apr16_appr_id IS NULL ) ) UNION ALL SELECT apr01_reg_date AS apr16_appl_date , apr01_reg_emp_id AS apr16_appl_emp_id , NULL AS apr16_note , apr01_stamp_id AS apr16_stamp_id , 1 AS apr16_stamp_qty , 'false' AS apr16_stamp_out_yn , apr01_receive_nm AS apr16_provide_co , apr01_title AS apr16_purpose , apr01_stamp_seq AS apr16_stamp_seq , NULL AS apr16_real_stamp_doc_id , ( SELECT sys10_reg_date FROM sys10_file WHERE sys10_parent_id = apr01_appr_id AND sys10_title_yn = 'true' ORDER BY sys10_file_id LIMIT 1 ) AS apr16_stamp_date , apr01_appr_id AS apr16_appr_id , apr01_status_cd AS status_cd FROM apr01_appr WHERE apr01_company_id = #{companyId} AND apr01_reg_date BETWEEN #{startDate} AND #{closeDate} AND apr01_status_cd = '30' UNION ALL SELECT apr99_reg_date AS apr16_appl_date , apr99_reg_emp_id AS apr16_appl_emp_id , NULL AS apr16_note , apr99_stamp_id AS apr16_stamp_id , 1 AS apr16_stamp_qty , 'false' AS apr16_stamp_out_yn , apr99_receive_nm AS apr16_provide_co , '<'||'b'||'style=color:#E33E31;'||'>'||'[폐기] '||'<'||'/b'||'>'||apr99_title AS apr16_purpose , apr99_stamp_seq AS apr16_stamp_seq , NULL AS apr16_real_stamp_doc_id , ( SELECT sys10_reg_date FROM sys10_file WHERE sys10_parent_id = apr99_appr_id AND sys10_title_yn = 'true' ORDER BY sys10_file_id LIMIT 1 ) AS apr16_stamp_date , apr99_appr_id AS apr16_appr_id , apr99_status_cd AS status_cd FROM apr99_appr_del WHERE apr99_company_id = #{companyId} AND apr99_reg_date BETWEEN #{startDate} AND #{closeDate} AND apr99_status_cd = '30' ) t INNER JOIN apr10_stamp ON apr10_stamp_id = apr16_stamp_id INNER JOIN emp01_person ON emp01_person_id = apr16_appl_emp_id WHERE 1=1
AND apr16_stamp_id = #{stampId}
AND COALESCE(apr16_stamp_out_yn, 'false') = 'true'
AND CONCAT(emp01_kor_nm, apr16_provide_co, apr16_purpose, apr16_stamp_seq) ILIKE #{searchText}
AND ( COALESCE(apr10_all_use_yn, 'false') = 'true' OR EXISTS ( SELECT 1 FROM org10_role_stamp WHERE org10_stamp_id = apr16_stamp_id AND org10_org_code_id = #{orgId} ) )

