mapper.select:
SELECT apr16_stamp_doc_id AS stamp_doc_id , apr16_appl_date AS appl_date , apr16_appl_emp_nm AS appl_emp_name , apr16_stamp_nm AS stamp_name , apr16_stamp_qty AS stamp_qty , apr16_provide_co AS provide_co , apr16_purpose AS purpose , apr16_appr_id AS appr_id , apr16_appr_status_nm AS appr_status_name , apr16_stamp_date AS stamp_date , CASE WHEN stamp_file_cnt = 0 THEN 'X' ELSE 'O' END AS stamp_file_chk , apr16_confirm_date AS confirm_date , apr16_confirmer_id AS confirmer_id , apr16_confirmer_nm AS confirmer_name FROM ( SELECT apr16_stamp_doc.* , a.emp01_kor_nm AS apr16_appl_emp_nm , b.emp01_kor_nm AS apr16_confirmer_nm , apr10_stamp_nm AS apr16_stamp_nm , CASE WHEN COALESCE(apr01_status_cd,'') = '' THEN null ELSE apr01_status_cd END AS apr16_appr_status_nm , ( SELECT COUNT(*) FROM sys10_file WHERE sys10_parent_id = apr16_appr_id AND sys10_stamp_yn = 'true' ) AS stamp_file_cnt FROM apr16_stamp_doc LEFT JOIN apr01_appr ON apr01_appr_id = apr16_appr_id LEFT JOIN apr10_stamp ON apr10_stamp_id = apr16_stamp_id LEFT JOIN emp01_person a ON a.emp01_person_id = apr16_appl_emp_id LEFT JOIN emp01_person b ON b.emp01_person_id = apr16_confirmer_id WHERE apr16_company_id = #{companyId} AND apr16_appl_date BETWEEN #{startDate} AND #{closeDate} AND apr16_appl_type = '3' AND COALESCE(apr01_status_cd,'') IN ('30','')
AND apr16_stamp_id = #{stampId}
) t WHERE 1=1
AND stamp_file_cnt = 0
ORDER BY apr16_appl_date DESC, apr16_stamp_doc_id DESC

mapper.update:
UPDATE apr16_stamp_doc
   SET apr16_confirmer_id = #{confirmerId}
     , apr16_confirm_date = #{confirmDate}
 WHERE apr16_stamp_doc_id = #{stampDocId}
   AND apr16_company_id   = #{companyId}
